# 仅用于生成初始文本；最终依据与核对字段以 ch5_patch_proposal.json 为准，不用于覆盖最终稿。
import json
from pathlib import Path
root=Path(__file__).resolve().parents[2]
blocks=json.loads((root/'_source/manuscript_blocks.json').read_text())
byid={b['id']:b for b in blocks}
ops=[]
def add(block_id,op,new_text,reason,style='BodyText'):
    d={'change_id':f'C5-{len(ops)+1:03d}','block_id':block_id,'op':op,'new_text':new_text,'style':style,'reason':reason}
    if op=='replace_text': d['old_text']=byid[block_id]['text']
    else: d['anchor_text']=byid[block_id]['text']
    d['order']=sum(x['block_id']==block_id and x['op']==op for x in ops)+1
    ops.append(d)
add('B0765','insert_after','第三章从训练阶段研究改写前后的可靠对应与成对学习，第四章从推理阶段研究组件修改后的关系依赖处理。两项研究作用于同一抽取流程，但各自的性能变化尚不能回答组合后的增益来自何处，也不能说明两阶段是否恢复了相同的关系。本章基于本稿所列模拟结果，在统一评价条件下分析训练与推理的组合表现，随后追踪正确关系的恢复来源及未命中关系的主要障碍，并以CDCP多源关系考察完整对象恢复的局限。','以两项前序研究尚未共同回答的问题引入本章；用一次材料性质说明保留模拟边界。')
add('B0767','replace_text','5.1 综合分析设置与比较范围','标题覆盖公共条件、比较层次和解释范围，不将综合分析误称为新增实验。','Heading2')
add('B0768','replace_text','本章沿用第二章的官方测试划分、原生对象身份和严格评价规则，以T0/I0作为继承配置，并在相同测试文档和三个种子上比较四种组合。其中，T1/I0仅引入第三章的训练配置，T0/I1仅引入第四章的推理配置，T1/I1同时采用两阶段方法。四种组合连接了前两章的结果，使训练变化、推理变化及其组合差异能够在共同参照下解释。','先明确四种配置和共同参照，减少读者在综合章反查符号的负担。')
add('B0768','insert_after','不同层次的比较所回答的问题有所区别，如表5-1所示。固定I0时的训练比较考察整套训练配置，固定T1时的推理比较考察既定模型输出上的修正增量；四格比较则进一步分析两阶段增益的重叠与交互。成对目标、共同接受和集合动作等具体机制仍须由相应消融判断，不能由完整配置的总增量替代。','以研究问题组织比较范围，承接第三、四章而不复述完整实验设置。')
add('B0770','insert_after','继承协议与外部系统另按各自的比较范围解释。补充表S2-1用于核查原MCR-BR协议下的继承配置，附录E保存MCR-BR已公开结果的转录，两者均不与本章的严格评价数值混算。附录G中的UniASA及Kawarada等的TextToText采用共同评价器，但保留各自架构与公开任务接口，因此用于系统层面的比较。实际CPU案例则来自CPU-BIO-SGD在训练侧拟合后的测试预测及固定规则处理，只用于说明可复核的错误变化。','保留原协议、外部对照、CPU诊断三类材料及边界；纠正“原稿已发表结果”的指代歧义。')
add('B0773','replace_text','5.2 两阶段组合结果与交互分析','把总量比较与阶段交互的两个问题明确写入标题。','Heading2')
add('B0773','insert_after','5.2.1 两阶段组合的总体表现','为总体性能和交互分析分设三级标题。','Heading3')
add('B0773','insert_after','表5-2汇总四种配置在AAEC与CDCP上的组件F1和关系F1，其中“±”表示三个种子的样本标准差。总体指标首先用于判断完整配置是否保持两阶段各自的改善方向，后续再通过关系身份追踪其变化来源。','表前先说明分析目的和统计展示方式。')
add('B0774','replace_text','表5-2 两阶段配置的组件与关系抽取性能','图表标题明确展示对象，保留编号及全部表内数值。','Caption')
add('B0775','insert_after','两种语料上，完整配置T1/I1的组件F1和关系F1均高于其余三种配置，关系F1分别为73.29和52.02。T1/I0与T0/I1也均高于继承配置，说明当前结果中，训练阶段的改变与推理阶段的修正分别对应正向的性能变化。完整配置的整体表现仍不能揭示两条路径恢复了哪些对象，这一问题将在关系成员分析中进一步展开。','为主结果提供直接解释，同时避免从总体数值跳到机制或因果结论。')
add('B0776','insert_before','5.2.2 阶段条件增量与交互','避免将固定另一因素时的差值误称为两因素设计的主效应。','Heading3')
add('B0776','insert_before','为区分阶段条件增量与组合关系，表5-3保留主要比较和探索性比较的身份，并列出逐种子差值及其95%置信区间。均值与差值分别由逐种子记录汇总后保留两位小数，因此展示均值的直接相减可能与表5-3相差0.01 pp；下文采用表5-3的配对差值。','交代比较身份和四舍五入显示差异，保留原表数值，不宣称新增原始预测复算。')
add('B0778','replace_text','在固定I0的条件下，引入T1使AAEC和CDCP的关系F1分别增加3.63 pp和4.89 pp；在T1基础上启用I1后，进一步增加4.48 pp和8.37 pp。完整配置相对T0/I0的差值分别为8.10 pp和13.26 pp。这些条件增量表明，训练后仍保留可由推理修正改善的空间，但不能将整套配置的差值全部归因于其中某一个学习项或决策动作。','将原段落过于跳跃的总差描述展开为条件比较，并保持机制归因边界。')
add('B0778','insert_after','交互项定义为(T1/I1−T1/I0)−(T0/I1−T0/I0)，其中配置符号在此表示相应的关系F1，用于比较推理增量是否随训练配置改变。AAEC的交互估计为−0.24 pp，CDCP为0.40 pp，两个95%置信区间均包含零。因此，当前结果尚不足以确认稳定的正向或负向交互，更不能仅凭两阶段的条件增量均为正就认定存在协同增益。图5-1直观展示了四种配置的关系F1变化；对象层面的互补与重叠仍需单独分析。','明确跨零区间的结论，区分总体改善、统计交互和对象重叠三个层次。')
add('B0783','replace_text','5.3 关系恢复来源与漏检成因','将“成员”“首个阻断”的记录术语转化为读者关心的分析问题。','Heading2')
add('B0783','insert_after','关系F1的变化同时受到正确关系恢复、错误关系减少和原有正确关系丢失的影响。为解释两阶段的组合表现，本节先在相同关系身份上比较恢复对象，再从端点和关系选择两个层次分析仍未命中的金标关系。','由总体指标转入对象追踪，说明两类诊断各自的作用。')
add('B0784','insert_before','5.3.1 两阶段恢复关系的重叠与差异','将成员分解独立为一个论证单元。','Heading3')
add('B0784','insert_before','表5-4以T0/I0中的正确关系为起点，将两条单独路径和完整配置新增的TP按语义键对齐。只有完整关系身份一致时才视为同一对象，从而区分两阶段共同恢复的关系、各自独有的恢复，以及仅在组合后出现的恢复。表中计数为三种子合计，用于对象分解，与逐种子F1均值属于不同的汇总量。','表前给出比较方法的必要信息，避免直接以计数表开节。')
add('B0786','replace_text','“共同恢复”指T1/I0与T0/I1相对T0/I0新增TP的交集，“训练独有”和“修正独有”分别指两者的差集，“组合独有”则指只在T1/I1中新增的TP。完整配置还可能丢失单路恢复或初始TP。表中各项满足“初始TP＋共同恢复＋训练独有＋修正独有＋组合独有−丢失单路恢复−丢失初始TP＝完整TP”，据此保留恢复与损失的完整对应关系。','保留原有成员定义及守恒关系，使用连贯叙述。')
add('B0786','insert_after','AAEC的训练独有和修正独有恢复分别为93条和36条，CDCP分别为35条和26条；两种语料共同恢复的数量均较少。该分布说明，在当前对象记录中，两条单独路径覆盖了部分不同的关系。仅由组合新增的TP分别为1条和3条，因此对象分析更直接地支持恢复范围存在差异，而不支持将总体增益主要解释为大量组合独有的恢复。','从既有计数中提炼恢复来源，避免把成员差异直接升级为统计协同。')
add('B0786','insert_after','完整配置没有丢失两条单独路径新增的TP，但分别丢失了9条和1条初始TP。由此可见，较高的总体F1与少量原有正确关系损失可以同时存在。恢复来源的分析需要保留这部分代价，也不能替代对FP变化及具体修正行为的检查。','同步报告损失，避免只强调新增TP或用TP分解解释全部F1变化。')
add('B0787','insert_before','5.3.2 未命中关系的端点与选择分析','以相邻两表组成漏检分析单元。','Heading3')
add('B0787','insert_before','关系恢复依赖于正确端点能够在最终图中同时成立。表5-5a将未命中的金标关系分为“端点缺失”和“端点齐全但未选”两类：前者尚不具备完整关系成立的组件条件，后者则是在端点已经齐全时仍未选中相应关系。该划分能够进一步判断，整体改善是否伴随不同类型漏检的同步减少。','先明确两类漏检的解释含义，再展示计数。')
add('B0788','insert_after','与T0/I0相比，T1/I1在AAEC上的端点缺失由707条降至588条，在CDCP上由340条降至272条；端点缺失仍是两种语料中较多的一类漏检。与此同时，端点齐全但未选的数量在AAEC上由138条变为135条，在CDCP上由123条变为126条，并未随端点恢复而一致下降。因此，组件条件得到改善之后，关系选择仍是需要单独考察的环节。','解释跨配置变化，强调端点恢复与关系选中并非同步，避免把减少量写成因果贡献率。')
add('B0789','insert_before','表5-5b进一步对完整配置中的未命中关系定位首个阻断。这里按表列顺序对每条未命中关系只归类一次，用以区分终态端点、完整候选槽位、评分及决策环节，避免同一漏检在多个环节被重复累计。','把归类说明移至表前，使读者先理解统计单位。')
add('B0791','replace_text','在完整配置中，AAEC除终态端点缺失外的漏检均归于“评分未过门”；CDCP还存在2条“完整槽位未入池”的关系，其余此类漏检同样集中在评分门限。未评分和超时的记录均为0，不能将当前漏检解释为这两类执行问题。“联合约束／接受门”列涵盖可行域、预算及接受条件，其含义也不等同于求解错误。','修正“最后一列”的错误定位，基于既有记录解释主要阻断而不作新的运行判断。')
add('B0791','insert_after','候选端点进入候选池与正确端点最终被选中是不同条件。池中存在相近或竞争跨度，不能视为金标关系的完整端点已经恢复。因此，上述首个阻断仅表示按既定顺序定位的诊断环节；它与端点—选择分解共同说明了漏检分布，但不构成对各环节影响的独立因果检验。','保留候选覆盖与终态选择的区分，并防止将诊断分类升级为因果归因。')
add('B0794','replace_text','5.4 多源关系的分组结果与局限','与参考论文中进一步分析及边界讨论的功能对应。','Heading2')
add('B0794','insert_after','CDCP的一条关系可以同时包含多个源组件，只有完整源集合、目标和标签均匹配时才计为TP。源成员数量增加后，部分端点的恢复并不等于整条关系恢复，因此仅看总体F1可能掩盖长源集合的困难。原生测试集包含218条单源、20条双源、6条三源和8条四源及以上关系，共252条，其中多源关系为34条。','将原段落中的分组总体提前，说明为何需要多源分组。')
add('B0795','insert_before','表5-6按完整源成员数分别报告四种配置的表现。TP、FP和FN为三个种子的计数合计，关系F1及其标准差则由逐种子指标汇总；不能用合计计数重新计算的单一F1替代所列均值。','在表前澄清计数合计与跨种子统计的区别。')
add('B0797','replace_text','单源关系构成CDCP总体结果的主要部分，完整配置的TP由继承配置的257条增加至318条，FP由397条减少至222条。多源分组的变化则更为有限：相对T1/I0，T1/I1在双源和三源组中的TP分别保持27条和10条，而FP分别由33条降至22条、由8条降至5条。这表明组内F1的增加可以主要来自错误预测减少，不能仅据F1上升就认定恢复了更多完整源集合。','补足原节缺失的分组结果解释，区分TP恢复与FP减少。')
add('B0797','insert_after','四源及以上关系中，完整配置的TP由2条增加至3条，但FN仍为21条，关系F1为15.02，低于其余各组。该结果反映出长源集合仍是当前配置的薄弱部分；不过，测试集仅有8条此类原生关系，三种子合计也不意味着获得了更多独立样本，因而不足以据此推断稳定的分组优势。各组结果仅用于描述误差分布，不承担新的显著性结论。','突出多源边界和独立样本数量限制，不把三个种子当成样本扩增。')
add('B0797','insert_after','完整源集合的评价单位在各配置和外部系统之间保持一致，不能将长源关系拆成多条独立边来增加TP。外部方法转换过程中对四源及以上对象的表达损失在附录G单列。结合分组结果，完整对象的表达覆盖、正确端点恢复和关系选择应分别检查，才能判断多源关系的限制出现在哪一环节。','保留完整对象评价和外部转换边界，使末段回到该节核心问题。')
add('B0801','replace_text','本章在统一协议下，将两阶段的总体表现、关系恢复来源和漏检分布联系起来。四格结果显示两阶段分别对应正向的条件增量，对象分析进一步表明，两条单独路径能够覆盖部分不同的关系，但组合过程仍会丢失少量初始TP，且交互区间尚不足以确认稳定协同。端点缺失和关系评分门限构成当前记录中的主要阻断，CDCP长源集合则保留了明显的恢复困难。因此，整体配置的改善、具体机制的独立贡献及复杂对象的适用范围应分别判断，成对项、共同接受、集合动作和重生成比较仍以各自受控分析为依据。','小结从汇总结果推进到综合判断与适用边界，去除不准确的“主效应”表述。')
